=⚽ *¡PRODE MUNDIAL - Predicciones de Mañana!* ⚽

Hola {{ $json.fields.nombre }}, estos son los partidos de mañana. Ingresá al link para dejar tus predicciones antes de que comiencen:

🔗 *Link del Formulario:* https://mgobeaalcoba.app.n8n.cloud/webhook/prode-mundial?player={{ $json.fields.telegram_chat_id }}

parameters.jsCode:
const allItems = $input.all();
if (!allItems[0].json.response) return [];
const fixtures = allItems[0].json.response;

// Filtramos por la liga correcta (World Cup = id 1)
const worldCupFixtures = fixtures.filter(match => match.league.id === 1);

return worldCupFixtures.map(match => {
  const homeTeam = match.teams.home.name;
  const awayTeam = match.teams.away.name;

  // Generamos el partido_id dinámico idéntico al del fixture de las 19 hs
  const partidoId = `${homeTeam.toLowerCase().replace(/\s+/g, '-')}-${awayTeam.toLowerCase().replace(/\s+/g, '-')}`;

  // Calculamos el ganador real de forma idéntica
  const ganadorReal = match.teams.home.winner ? homeTeam : (match.teams.away.winner ? awayTeam : 'Ninguno (Empate)');

  // Extraemos solo la fecha YYYY-MM-DD de la cadena completa ISO
  const fixtureDate = match.fixture.date ? match.fixture.date.split('T')[0] : null;

  return {
    json: {
      partido_id: partidoId,
      fixture_id: match.fixture.id,
      fixture_date: fixtureDate,
      equipo_1: homeTeam,
      equipo_2: awayTeam,
      goles_equipo_1: match.goals.home,
      goles_equipo_2: match.goals.away,
      ganador: ganadorReal,
      timestamp: match.fixture.timestamp,
      termino: ['FT', 'PEN'].includes(match.fixture.status.short)
    }
  };
});

// Cambiamos la referencia al nodo de Airtable que ya guardó los resultados reales
const results = $('Upsert Fixture Ayer').all();
const predictions = $('Obtener Predicciones').all();

const playerPoints = {};

// Tomamos la fecha del día en que se procesan los partidos finalizados
const fechaProceso = new Date().toISOString().split('T')[0];

predictions.forEach(pred => {
  const p = pred.json.fields; 

  if (!p) return; // Salvaguarda por si viene una fila vacía

  // Buscamos el partido real dentro de los campos de 'Upsert Fixture Ayer'
  const actualMatch = results.find(r => Number(r.json.fields.fixture_id) === Number(p.fixture_id));

  if (actualMatch && actualMatch.json.fields.termino) {
    const matchReal = actualMatch.json.fields;
    let pts = 0;

    // 1. Verificamos si coincide el ganador real o el empate (Acierto Base)
    if (p.prediccion_ganador === matchReal.ganador) {

      // 2. Verificamos si TAMBIÉN acertó los goles exactos de ambos equipos
      const coincidenGoles1 = Number(p.goles_equipo_1) === Number(matchReal.goles_equipo_1);
      const coincidenGoles2 = Number(p.goles_equipo_2) === Number(matchReal.goles_equipo_2);

      if (coincidenGoles1 && coincidenGoles2) {
        pts = 3; // Marcador perfecto
      } else {
        pts = 1; // Solo ganador/empate
      }
    }

    // Acumulamos los puntos agrupando por el ID de jugador (telegram_chat_id)
    if (!playerPoints[p.id_jugador]) {
      playerPoints[p.id_jugador] = 0;
    }
    playerPoints[p.id_jugador] += pts;
  }
});

// Mapeamos el consolidado final al formato que requiere la tabla puntaje_jugadores
return Object.keys(playerPoints).map(id => ({
  json: {
    id_jugador: id,
    puntos_del_dia: playerPoints[id],
    fecha: fechaProceso
  }
}));

// 1. Los ítems del input directo son los Jugadores
const infoJugadores = $input.all();

// 2. Recuperamos de forma cruzada el historial completo desde el nodo de puntajes
let itemsPuntajes = [];
try {
  itemsPuntajes = $('Traer Puntajes').all();
} catch (e) {
  // Salvaguarda por si falla la herencia en modo de prueba
}

const playerPoints = {};
const playerHoyPoints = {};

// Tomamos la fecha del día en formato YYYY-MM-DD
const fechaProceso = new Date().toISOString().split('T')[0];

// ==========================================
// PROCESAR Y ACUMULAR PUNTOS HISTÓRICOS
// ==========================================
itemsPuntajes.forEach(pred => {
  const p = pred.json.fields; 
  if (!p) return;

  const id = p.id_jugador ? p.id_jugador.toString() : '';
  if (!id) return;

  // Inicializamos el acumulador si no existe
  if (!playerPoints[id]) {
    playerPoints[id] = 0;
  }

  // Sumamos al histórico total
  playerPoints[id] += Number(p.puntos_del_dia || 0);

  // Si el registro coincide con la fecha de hoy, lo guardamos para el reporte diario
  if (p.fecha === fechaProceso) {
    if (!playerHoyPoints[id]) {
      playerHoyPoints[id] = 0;
    }
    playerHoyPoints[id] += Number(p.puntos_del_dia || 0);
  }
});

// ==========================================
// MAPEAR PERFILES Y CREAR EL RANKING FINAL
// ==========================================
const listaRanking = infoJugadores.map(jugador => {
  const fields = jugador.json.fields;
  if (!fields) return null;

  const chatId = fields.telegram_chat_id ? fields.telegram_chat_id.toString() : '';

  return {
    nombre: fields.nombre ? fields.nombre.trim() : 'Invitado',
    pais: fields.pais || 'No especificado',
    telegram_chat_id: chatId,
    puntos_totales: playerPoints[chatId] || 0,
    puntos_ganados_hoy: playerHoyPoints[chatId] || 0
  };
}).filter(j => j !== null); // Limpiamos registros nulos por si las dudas

// Ordenamos de mayor a menor según el puntaje histórico acumulado para armar el podio
listaRanking.sort((a, b) => b.puntos_totales - a.puntos_totales);

// Mapeamos el output final inyectando el orden/puesto numérico exacto para la IA
return listaRanking.map((jugador, index) => {
  return {
    json: {
      nombre: jugador.nombre,
      pais: jugador.pais,
      puntos_ganados_hoy: jugador.puntos_ganados_hoy,
      puntos_totales_acumulados: jugador.puntos_totales,
      puesto_ranking: `${index + 1}º`,
      telegram_chat_id: jugador.telegram_chat_id,
      fecha: fechaProceso
    }
  };
});

