const matches = $('Buscar Partidos Activos').all();
const formInput = $('Webhook').first(); 
const queryParams = formInput.json.query || {};

// Capturamos el ID del jugador desde la URL (tu telegram_chat_id)
const playerId = queryParams.player || 'Invitado';

// Intentamos recuperar de forma segura el nombre real desde el nuevo nodo de Airtable
let playerName = 'Invitado';
try {
  const jugadorRecord = $('Buscar Jugador').first();
  if (jugadorRecord && jugadorRecord.json && jugadorRecord.json.fields) {
    playerName = jugadorRecord.json.fields.nombre;
  }
} catch (e) {
  // Si no encuentra ejecuciones previas del nodo, se mantiene seguro como 'Invitado'
}

// ==========================================
// CONSTRUIR LA INTERFAZ WEB (GET)
// ==========================================
let matchFieldsHTML = '';
matches.forEach(m => {
  const p = m.json.fields; 

  if (p) {
    matchFieldsHTML += `
      <div class="match-card">
        <label class="match-label">${p.equipo_1} vs ${p.equipo_2}</label>

        <div style="margin-bottom: 12px;">
          <select name="match_${p.fixture_id}" required class="match-select">
            <option value="" disabled selected>¿Quién gana?</option>
            <option value="${p.equipo_1}">Gana ${p.equipo_1}</option>
            <option value="${p.equipo_2}">Gana ${p.equipo_2}</option>
            <option value="Ninguno (Empate)">Empate</option>
          </select>
        </div>

        <div class="goals-container" style="display: flex; gap: 10px; align-items: center; justify-content: space-between;">
          <div style="flex: 1; display: flex; align-items: center; gap: 5px;">
            <span style="font-size: 0.85em; color: #666; min-width: 50px; text-overflow: ellipsis; overflow: hidden; white-space: nowrap;">${p.equipo_1}:</span>
            <input type="number" name="match_${p.fixture_id}_goles1" min="0" required placeholder="0" class="goals-input" style="width: 100%; padding: 6px; border-radius: 4px; border: 1px solid #cbd5e1;">
          </div>
          <div style="flex: 1; display: flex; align-items: center; gap: 5px;">
            <span style="font-size: 0.85em; color: #666; min-width: 50px; text-overflow: ellipsis; overflow: hidden; white-space: nowrap;">${p.equipo_2}:</span>
            <input type="number" name="match_${p.fixture_id}_goles2" min="0" required placeholder="0" class="goals-input" style="width: 100%; padding: 6px; border-radius: 4px; border: 1px solid #cbd5e1;">
          </div>
        </div>
      </div>
    `;
  }
});

const htmlForm = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Prode Mundial 🏆</title>
  <style>
    body { font-family: sans-serif; background: #f4f6f9; color: #333; padding: 20px; }
    .container { max-width: 500px; background: white; margin: 0 auto; padding: 30px; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }

    /* Estilos de la Cabecera de Logos */
    .brand-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; padding-bottom: 15px; border-bottom: 2px solid #edf2f7; }
    .logo-henry { height: 45px; max-width: 150px; object-fit: contain; border-radius: 4px; }
    .logo-cup { height: 50px; width: 50px; object-fit: cover; border-radius: 50%; border: 2px solid #3483FA; }

    h2 { text-align: center; color: #1a365d; margin-top: 10px; margin-bottom: 5px; }
    .match-card { margin-bottom: 20px; padding: 15px; border: 1px solid #e2e8f0; border-radius: 6px; background: #fafafa; }
    .match-label { font-weight: bold; display: block; margin-bottom: 12px; color: #2d3748; font-size: 1.05em; border-bottom: 1px solid #edf2f7; padding-bottom: 8px; }
    .match-select { width: 100%; padding: 8px; border-radius: 4px; border: 1px solid #cbd5e1; background: #fff; color: #333; }
    .btn-submit { width: 100%; background: #3483FA; color: white; border: none; padding: 12px; font-size: 16px; border-radius: 4px; cursor: pointer; font-weight: bold; margin-top: 10px; }
    .btn-submit:hover { background: #2b6cb0; }
  </style>
</head>
<body>
  <div class="container">
    <div class="brand-header">
      <img src="https://assets.soyhenry.com/logoOG.png" alt="Henry" class="logo-henry">
      <img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTe37IZj18o3Bqd81TZJgPsji7zwspaulCak3b7-xA2gzHpH2JtJkkdfKcq&s=10" alt="Copa del Mundo" class="logo-cup">
    </div>

    <h2>Prode Mundial 🏆</h2>
    <p style="text-align:center; color: #2d3748; font-size: 1.1em; font-weight: 500; margin-bottom: 25px;">
      ¡Hola, <span style="color: #3483FA; font-weight: bold;">${playerName.trim()}</span>! Dejá tus predicciones:
    </p>

    <form method="POST">
      <input type="hidden" name="player_id" value="${playerId}">
      ${matchFieldsHTML}
      <button type="submit" class="btn-submit">Enviar Mis Predicciones</button>
    </form>
  </div>
</body>
</html>
`;

return [{ json: { htmlContent: htmlForm } }];

const formInput = $('Webhook - Recibir POST').first();
const queryParams = formInput.json.query || {};
const body = formInput.json.body || {};
const predictionsMap = {};

// Capturamos el ID único (telegram_chat_id) que viaja oculto o en la URL
const playerId = body.player_id || queryParams.player || 'Invitado';

// Iteramos las claves enviadas en el formulario x-www-form-urlencoded
Object.keys(body).forEach(key => {
  if (key.startsWith('match_')) {
    const parts = key.split('_'); // match_[fixture_id], match_[fixture_id]_goles1, etc.
    const fixtureId = parts[1];

    if (!predictionsMap[fixtureId]) {
      predictionsMap[fixtureId] = {
        id_jugador: playerId,
        fixture_id: Number(fixtureId)
      };
    }

    if (parts.length === 2) {
      // Nombre del ganador elegido en el select
      predictionsMap[fixtureId].prediccion_ganador = body[key];
    } else if (parts[2] === 'goles1') {
      predictionsMap[fixtureId].goles_equipo_1 = Number(body[key]);
    } else if (parts[2] === 'goles2') {
      predictionsMap[fixtureId].goles_equipo_2 = Number(body[key]);
    }
  }
});

// Retornamos la data expandida en filas individuales para que Airtable procese cada registro
return Object.values(predictionsMap).map(pred => ({ json: pred }));
